<?php
namespace App\Http\Controllers;
use App\Models\Order;use App\Models\OrderItem;use App\Models\Product;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;use Illuminate\View\View;use Illuminate\Http\RedirectResponse;
class CheckoutController {
 public function create():View|RedirectResponse{if(empty(session('cart',[])))return redirect()->route('store.index')->with('status','Your cart is empty.');$products=Product::whereIn('id',array_keys(session('cart')))->get()->keyBy('id');$subtotal=$products->sum(fn($p)=>$p->price_cents*session('cart')[$p->id]);return view('checkout.create',compact('products','subtotal'));}
 public function store(Request $r):RedirectResponse{$d=$r->validate(['customer_name'=>'required|string|max:160','email'=>'required|email|max:190','phone'=>'nullable|string|max:40','address'=>'required|string|max:255','city'=>'required|string|max:120','postal_code'=>'required|string|max:30','country'=>'required|string|max:100','payment_method'=>'required|in:cash_on_delivery,bank_transfer']);$cart=session('cart',[]);if(!$cart)return redirect()->route('store.index');$order=DB::transaction(function()use($cart,$d,$r){$products=Product::whereIn('id',array_keys($cart))->orderBy('id')->lockForUpdate()->get()->keyBy('id');if($products->count()!=count($cart))throw ValidationException::withMessages(['cart'=>'A product is no longer available.']);$total=0;foreach($cart as $id=>$qty){$p=$products[$id];if(!$p->is_active||$p->stock<$qty)throw ValidationException::withMessages(['cart'=>"Insufficient stock for {$p->name}."]);$total+=$p->price_cents*$qty;}$order=Order::create([...$d,'user_id'=>$r->user()->id,'order_number'=>'ORD-'.Str::upper(Str::random(10)),'subtotal_cents'=>$total,'shipping_cents'=>0,'total_cents'=>$total,'status'=>'pending','payment_status'=>'pending']);foreach($cart as $id=>$qty){$p=$products[$id];OrderItem::create(['order_id'=>$order->id,'product_id'=>$p->id,'product_name'=>$p->name,'quantity'=>$qty,'unit_price_cents'=>$p->price_cents]);$p->decrement('stock',$qty);}return $order;});session()->forget('cart');return redirect()->route('orders.success',$order)->with('order_number',$order->order_number);}
 public function success(Request $r,Order $order):View{abort_unless($r->user()->id===$order->user_id&&session('order_number')===$order->order_number,403);return view('checkout.success',['order'=>$order->load('items')]);}}
